import React, { useState, useEffect } from 'react';
import { Table, Card, Button, Space, Tag, Modal, Select, message, Popconfirm, Tooltip, Form, Input, DatePicker, Upload, Row, Col, Switch } from 'antd';
import { UserAddOutlined, UserSwitchOutlined, DownloadOutlined, DeleteOutlined, DownOutlined, PlusOutlined, UploadOutlined } from '@ant-design/icons';
import { API_BASE_URL } from '../../../utils/api';
import styles from './RegistrationManagement.module.css';
import * as XLSX from 'xlsx';

const { Option } = Select;

const RegistrationManagement = () => {
  const [registrations, setRegistrations] = useState([]);
  const [loading, setLoading] = useState(false);
  const [selectedRows, setSelectedRows] = useState([]);
  const [batchDeleteModalVisible, setBatchDeleteModalVisible] = useState(false);
  const [events, setEvents] = useState({});
  const [groupedData, setGroupedData] = useState([]);
  const [addModalVisible, setAddModalVisible] = useState(false);
  const [addForm] = Form.useForm();
  const [selectedEvent, setSelectedEvent] = useState(null);
  const [selectedEventSessions, setSelectedEventSessions] = useState([]);
  const [importModalVisible, setImportModalVisible] = useState(false);
  const [previewData, setPreviewData] = useState([]);
  const [selectedEventForImport, setSelectedEventForImport] = useState(null);
  const [selectedSessionForImport, setSelectedSessionForImport] = useState(null);

  // 獲取報名資料後的處理函數
  const processRegistrations = (data) => {
    // 按活動和場次分組
    const grouped = {};
    data.forEach(registration => {
      const eventId = registration.attributes.event?.data?.id;
      const sessionIndex = registration.attributes.sessionIndex;
      const eventTitle = registration.attributes.event?.data?.attributes?.title || '未知活動';
      const eventSessions = registration.attributes.event?.data?.attributes?.session || [];
      const sessionObj = eventSessions[sessionIndex];
      const sessionName = sessionObj?.location || `場次 ${sessionIndex + 1}`;
      const key = `${eventId}-${sessionIndex}`;

      if (!grouped[key]) {
        grouped[key] = {
          key,
          eventId,
          sessionIndex,
          eventTitle,
          sessionName,
          registrations: [],
          totalCount: 0,
          confirmedCount: 0
        };
      }

      grouped[key].registrations.push(registration);
      grouped[key].totalCount++;
      if (registration.attributes.status === 'confirmed') {
        grouped[key].confirmedCount++;
      }
    });

    // 轉換為數組格式並按活動名稱和場次排序
    const groupedArray = Object.values(grouped).sort((a, b) => {
      // 先按活動名稱排序
      const titleCompare = a.eventTitle.localeCompare(b.eventTitle);
      if (titleCompare !== 0) return titleCompare;
      // 如果活動名稱相同，則按場次索引排序
      return a.sessionIndex - b.sessionIndex;
    });
    
    console.log('分組後的資料:', groupedArray);
    setGroupedData(groupedArray);
  };

  // 修改獲取報名資料的函數
  const fetchRegistrations = async () => {
    setLoading(true);
    try {
      // 修改 API 請求，確保獲取完整的活動資訊
      const response = await fetch(`${API_BASE_URL}/api/registrations?populate[event][populate][0]=session&sort=createdAt:desc`);
      const data = await response.json();
      
      if (response.ok) {
        console.log('報名資料:', data.data);
        setRegistrations(data.data || []);
        processRegistrations(data.data || []);
      } else {
        console.log('獲取報名資料失敗:', data);
        setRegistrations([]);
        setGroupedData([]);
      }
    } catch (error) {
      console.error('獲取報名資料錯誤:', error);
      setRegistrations([]);
      setGroupedData([]);
    } finally {
      setLoading(false);
    }
  };

  // 獲取活動資料
  const fetchEvents = async () => {
    try {
      console.log('開始獲取活動資料');
      const response = await fetch(`${API_BASE_URL}/api/events?populate=*`);
      const data = await response.json();
      
      console.log('活動資料回應:', data);
      
      if (response.ok) {
        // 將活動資料轉為 Map 結構，方便查詢
        const eventsMap = {};
        (data.data || []).forEach(event => {
          console.log('處理活動:', event.id, event.attributes);
          eventsMap[event.id] = {
            ...event.attributes,
            // 確保正確獲取 session 資料
            sessions: Array.isArray(event.attributes.session) 
              ? event.attributes.session 
              : event.attributes.session?.data?.map(s => s.attributes.name) || []
          };
        });
        console.log('處理後的活動資料:', eventsMap);
        setEvents(eventsMap);
      } else {
        console.error('獲取活動資料失敗:', data);
      }
    } catch (error) {
      console.error('獲取活動資料錯誤:', error);
    }
  };

  useEffect(() => {
    fetchRegistrations();
    fetchEvents();
  }, []);

  // 根據sessionIndex獲取場次名稱
  const getSessionName = (eventId, sessionIndex) => {
    if (!eventId || sessionIndex === undefined || sessionIndex === null) {
      return '未指定場次';
    }

    const event = events[eventId];
    if (!event) {
      return '未知活動';
    }

    const sessions = event.sessions || [];
    if (!sessions || !sessions.length) {
      return `場次 ${sessionIndex + 1}`;
    }

    // 確保 sessionIndex 在有效範圍內
    if (sessionIndex < 0 || sessionIndex >= sessions.length) {
      return `場次 ${sessionIndex + 1}`;
    }

    return sessions[sessionIndex] || `場次 ${sessionIndex + 1}`;
  };

  // 刪除報名資料
  const handleDelete = async (record) => {
    try {
      const response = await fetch(`${API_BASE_URL}/api/registrations/${record.id}`, {
        method: 'DELETE',
        headers: {
          'Content-Type': 'application/json'
        }
      });

      if (!response.ok) {
        throw new Error('刪除失敗');
      }

      message.success('成功刪除報名資料');
      await fetchRegistrations();
    } catch (error) {
      console.error('刪除失敗:', error);
      message.error('刪除失敗');
    }
  };

  // 導出 Excel
  const handleExport = () => {
    // 準備導出數據
    const exportData = registrations.map(({ attributes }) => {
      return {
        '活動名稱': attributes.event?.data?.attributes?.title || '未知活動',
        '場次': getSessionName(attributes.event?.data?.id, attributes.sessionIndex),
        '姓名': attributes.name,
        '電話': attributes.phone,
        '電子郵件': attributes.email,
        '海外投資經驗': attributes.has_overseas_investment ? '有' : '無',
        '投資預算': (() => {
          const budgetMap = {
            budget_unknown: '未知',
            budget_under_ten: '一千萬以下',
            budget_ten_to_twenty: '一千萬到兩千萬',
            budget_twenty_to_thirty: '兩千萬到三千萬',
            budget_above_thirty: '三千萬以上'
          };
          return budgetMap[attributes.budget_range] || '未知';
        })(),
        '投資說明': attributes.overseas_investment_notes || '',
        '出席人數': `${attributes.attendanceCount || 1}人`,
        '備註': attributes.notes || '',
        '報名時間': new Date(attributes.createdAt).toLocaleString(),
        '狀態': attributes.status === 'confirmed' ? '已轉換' : '未處理'
      };
    });

    // 創建工作表
    const ws = XLSX.utils.json_to_sheet(exportData);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "報名資料");

    // 導出文件
    XLSX.writeFile(wb, `活動報名資料_${new Date().toISOString().split('T')[0]}.xlsx`);
  };

  // 下載範本
  const handleTemplateDownload = () => {
    const template = [{
      '活動名稱': '(必填)',
      '場次': '(必填)',
      '姓名': '(必填)',
      '電話': '(必填)',
      '電子郵件': '(必填)',
      '海外投資經驗': '有/無',
      '投資預算': '未知/一千萬以下/一千萬到兩千萬/兩千萬到三千萬/三千萬以上',
      '投資說明': '',
      '出席人數': '1-5人',
      '備註': ''
    }];

    const ws = XLSX.utils.json_to_sheet(template);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "範本");
    XLSX.writeFile(wb, "活動報名範本.xlsx");
  };

  // 處理 Excel 上傳
  const handleExcelUpload = (file) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = new Uint8Array(e.target.result);
        const workbook = XLSX.read(data, { type: 'array' });
        const sheetName = workbook.SheetNames[0];
        const worksheet = workbook.Sheets[sheetName];
        const jsonData = XLSX.utils.sheet_to_json(worksheet);

        // 轉換數據格式
        const previewData = jsonData.map(row => {
          // 解析投資預算範圍
          const getBudgetRange = (budget) => {
            const budgetMap = {
              '未知': 'budget_unknown',
              '一千萬以下': 'budget_under_ten',
              '三千萬以上': 'budget_above_thirty',
              '一千萬到兩千萬': 'budget_ten_to_twenty',
              '兩千萬到三千萬': 'budget_twenty_to_thirty'
            };
            return budgetMap[budget] || 'budget_unknown';
          };

          // 解析出席人數
          const getAttendanceCount = (attendance) => {
            const count = parseInt(attendance?.replace(/[^0-9]/g, '')) || 1;
            return count < 1 ? 1 : count > 5 ? 5 : count;
          };

          return {
            event_title: row['活動名稱'] || '',
            session_name: row['場次'] || '',
            name: row['姓名'] || '',
            phone: row['電話'] || '',
            email: row['電子郵件'] || '',
            has_overseas_investment: row['海外投資經驗'] === '有',
            budget_range: getBudgetRange(row['投資預算']),
            overseas_investment_notes: row['投資說明'] || '',
            attendanceCount: getAttendanceCount(row['出席人數']),
            notes: row['備註'] || ''
          };
        });

        // 驗證必填欄位
        const invalidData = previewData.filter(data => 
          !data.event_title || 
          !data.session_name || 
          !data.name || 
          !data.phone || 
          !data.email
        );

        if (invalidData.length > 0) {
          message.error('Excel 檔案中有缺少必填欄位的資料，請檢查後重新上傳');
          return;
        }

        setPreviewData(previewData);
        setImportModalVisible(true);
      } catch (error) {
        console.error('解析 Excel 文件錯誤:', error);
        message.error('無法解析 Excel 文件，請確保文件格式正確');
      }
    };
    reader.readAsArrayBuffer(file);
    return false;
  };

  // 轉換為客戶
  const convertToCustomer = async (record) => {
    try {
      // 準備客戶資料
      const customerData = {
        data: {
          name: record.attributes.name,
          phone: record.attributes.phone,
          email: record.attributes.email,
          has_overseas_investment: record.attributes.has_overseas_investment,
          budget_range: record.attributes.budget_range,
          overseas_investment_notes: record.attributes.overseas_investment_notes,
          notes: record.attributes.notes,
          source: 'event',
          source_detail: `${record.attributes.event?.data?.attributes?.title || '未知活動'} - ${
            getSessionName(record.attributes.event?.data?.id, record.attributes.sessionIndex)
          }`,
          status: 'potential'
        }
      };

      // 創建客戶
      const customerResponse = await fetch(`${API_BASE_URL}/api/customers`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify(customerData)
      });

      if (!customerResponse.ok) {
        throw new Error('創建客戶失敗');
      }

      // 更新報名狀態
      const updateResponse = await fetch(`${API_BASE_URL}/api/registrations/${record.id}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({
          data: {
            status: 'confirmed'
          }
        })
      });

      if (!updateResponse.ok) {
        throw new Error('更新報名狀態失敗');
      }

      message.success('成功轉換為客戶！');
      fetchRegistrations(); // 重新載入報名資料
    } catch (error) {
      console.error('轉換客戶失敗:', error);
      message.error('轉換失敗，請稍後再試');
    }
  };

  // 批量轉換為客戶
  const handleBatchConvert = async () => {
    if (!selectedRows.length) {
      message.warning('請選擇要轉換的報名資料');
      return;
    }

    try {
      // 過濾已轉換的報名
      const unconfirmedRegistrations = selectedRows.filter(
        record => record.attributes.status !== 'confirmed'
      );

      if (!unconfirmedRegistrations.length) {
        message.warning('選擇的報名資料都已經轉換過了');
        return;
      }

      // 批量轉換
      await Promise.all(
        unconfirmedRegistrations.map(async (record) => {
          const customerData = {
            data: {
              name: record.attributes.name,
              phone: record.attributes.phone,
              email: record.attributes.email,
              has_overseas_investment: record.attributes.has_overseas_investment,
              budget_range: record.attributes.budget_range,
              overseas_investment_notes: record.attributes.overseas_investment_notes,
              notes: record.attributes.notes,
              source: 'event',
              source_detail: `${record.attributes.event?.data?.attributes?.title || '未知活動'} - ${
                getSessionName(record.attributes.event?.data?.id, record.attributes.sessionIndex)
              }`,
              status: 'potential'
            }
          };

          // 創建客戶
          await fetch(`${API_BASE_URL}/api/customers`, {
            method: 'POST',
            headers: {
              'Content-Type': 'application/json'
            },
            body: JSON.stringify(customerData)
          });

          // 更新報名狀態
          await fetch(`${API_BASE_URL}/api/registrations/${record.id}`, {
            method: 'PUT',
            headers: {
              'Content-Type': 'application/json'
            },
            body: JSON.stringify({
              data: {
                status: 'confirmed'
              }
            })
          });
        })
      );

      message.success(`成功轉換 ${unconfirmedRegistrations.length} 筆報名資料為客戶！`);
      setSelectedRows([]); // 清空選擇
      fetchRegistrations(); // 重新載入報名資料
    } catch (error) {
      console.error('批量轉換失敗:', error);
      message.error('批量轉換失敗，請稍後再試');
    }
  };

  // 批量刪除報名資料
  const handleBatchDelete = async () => {
    if (selectedRows.length === 0) {
      message.warning('請先選擇要刪除的報名資料');
      return;
    }

    setBatchDeleteModalVisible(true);
  };

  // 確認批量刪除
  const confirmBatchDelete = async () => {
    try {
      setLoading(true);
      
      // 批量刪除所選記錄
      await Promise.all(selectedRows.map(record => 
        fetch(`${API_BASE_URL}/api/registrations/${record.id}`, {
          method: 'DELETE',
          headers: {
            'Content-Type': 'application/json'
          }
        })
      ));

      message.success(`成功刪除 ${selectedRows.length} 筆報名資料`);
      setSelectedRows([]);
      setBatchDeleteModalVisible(false);
      await fetchRegistrations();
    } catch (error) {
      console.error('批量刪除失敗:', error);
      message.error('批量刪除失敗');
    } finally {
      setLoading(false);
    }
  };

  // 監聽選擇的活動變化
  const handleEventChange = (eventId) => {
    setSelectedEvent(eventId);
    const event = events[eventId];
    if (event && event.sessions) {
      setSelectedEventSessions(event.sessions);
    } else {
      setSelectedEventSessions([]);
    }
  };

  // 處理新增報名
  const handleAdd = async () => {
    try {
      const values = await addForm.validateFields();
      
      const registrationData = {
        data: {
          name: values.name,
          phone: values.phone,
          email: values.email,
          has_overseas_investment: values.has_overseas_investment,
          budget_range: values.budget_range,
          overseas_investment_notes: values.overseas_investment_notes,
          notes: values.notes,
          attendanceCount: values.attendanceCount,
          event: values.event,
          sessionIndex: values.sessionIndex,
          status: 'pending'
        }
      };

      const response = await fetch(`${API_BASE_URL}/api/registrations`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify(registrationData)
      });

      if (!response.ok) {
        throw new Error('新增報名失敗');
      }

      message.success('成功新增報名！');
      setAddModalVisible(false);
      addForm.resetFields();
      fetchRegistrations();
    } catch (error) {
      console.error('新增報名失敗:', error);
      if (error.name === 'ValidationError') {
        message.error('請填寫必要欄位');
      } else {
        message.error('新增失敗，請稍後再試');
      }
    }
  };

  // 批量匯入報名資料
  const handleBatchImport = async () => {
    if (!selectedEventForImport || selectedSessionForImport === null) {
      message.error('請選擇活動和場次');
      return;
    }

    setLoading(true);
    try {
      // 批量創建報名資料
      await Promise.all(previewData.map(data => 
        fetch(`${API_BASE_URL}/api/registrations`, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json'
          },
          body: JSON.stringify({
            data: {
              ...data,
              event: selectedEventForImport,
              sessionIndex: selectedSessionForImport,
              status: 'pending'
            }
          })
        })
      ));

      message.success(`成功匯入 ${previewData.length} 筆報名資料`);
      setImportModalVisible(false);
      setPreviewData([]);
      setSelectedEventForImport(null);
      setSelectedSessionForImport(null);
      await fetchRegistrations();
    } catch (error) {
      console.error('批量匯入失敗:', error);
      message.error('批量匯入失敗');
    } finally {
      setLoading(false);
    }
  };

  // 主表格列定義
  const columns = [
    {
      title: '活動名稱',
      dataIndex: 'eventTitle',
      key: 'eventTitle',
      render: (text) => (
        <Tooltip title={text}>
          <div style={{ 
            cursor: 'pointer', 
            color: '#1890ff'
          }}>
            {text.length > 30 ? `${text.substring(0, 30)}...` : text}
          </div>
        </Tooltip>
      ),
    },
    {
      title: '場次',
      dataIndex: 'sessionName',
      key: 'sessionName',
      render: (text) => {
        const sessionText = typeof text === 'string' ? text : '';
        if (sessionText.trim() === '') {
          return <span style={{ color: '#c0c0c0' }}>未指定場次</span>;
        }
        const displayText = sessionText.length > 15 ? `${sessionText.substring(0, 15)}...` : sessionText;
        return (
          <Tooltip title={sessionText}>
            <div style={{ cursor: 'pointer', color: '#666' }}>
              {displayText}
            </div>
          </Tooltip>
        );
      },
    },
    {
      title: '報名總數',
      dataIndex: 'totalCount',
      key: 'totalCount',
      render: (text) => (
        <div style={{ 
          fontSize: '16px',
          color: '#52c41a'
        }}>
          {text}
        </div>
      ),
    },
    {
      title: '已轉換數',
      dataIndex: 'confirmedCount',
      key: 'confirmedCount',
      render: (text, record) => (
        <Tag color="green" style={{ padding: '4px 8px', fontSize: '14px' }}>
          {`${text}/${record.totalCount}`}
        </Tag>
      ),
    },
  ];

  // 展開行的渲染函數
  const expandedRowRender = (record) => {
    const columns = [
      {
        title: '姓名',
        dataIndex: ['attributes', 'name'],
        key: 'name',
        render: (text) => (
          <div style={{ fontWeight: 'bold' }}>{text}</div>
        ),
      },
      {
        title: '電話',
        dataIndex: ['attributes', 'phone'],
        key: 'phone',
      },
      {
        title: '電子郵件',
        dataIndex: ['attributes', 'email'],
        key: 'email',
      },
      {
        title: '海外投資',
        dataIndex: ['attributes', 'has_overseas_investment'],
        key: 'has_overseas_investment',
        render: (value) => (
          <Tag color={value ? 'green' : 'default'}>
            {value ? '有' : '無'}
          </Tag>
        ),
      },
      {
        title: '投資預算',
        dataIndex: ['attributes', 'budget_range'],
        key: 'budget_range',
        render: (value) => {
          const budgetMap = {
            budget_unknown: '未知',
            budget_under_ten: '一千萬以下',
            budget_ten_to_twenty: '一千萬到兩千萬',
            budget_twenty_to_thirty: '兩千萬到三千萬',
            budget_above_thirty: '三千萬以上'
          };
          return budgetMap[value] || '未知';
        },
      },
      {
        title: '投資說明',
        dataIndex: ['attributes', 'overseas_investment_notes'],
        key: 'overseas_investment_notes',
        ellipsis: true,
        render: (text) => {
          if (!text || text.trim() === '') {
            return <span style={{ color: '#c0c0c0' }}>無</span>;
          }
          return (
            <Tooltip title={text}>
              <div style={{ cursor: 'pointer', color: '#666' }}>
                {text.length > 20 ? `${text.substring(0, 20)}...` : text}
              </div>
            </Tooltip>
          );
        },
      },
      {
        title: '出席人數',
        dataIndex: ['attributes', 'attendanceCount'],
        key: 'attendanceCount',
        render: (value) => {
          const count = parseInt(value) || 1;
          return `${count}人`;
        }
      },
      {
        title: '備註',
        key: 'notes',
        ellipsis: true,
        render: (_, record) => {
          const notes = typeof record.attributes.notes === 'string' ? record.attributes.notes : '';
          if (notes.trim() === '') {
            return <span style={{ color: '#c0c0c0' }}>無</span>;
          }
          return (
            <Tooltip title={notes}>
              <div style={{ cursor: 'pointer', color: '#666' }}>
                {notes.length > 20 ? `${notes.substring(0, 20)}...` : notes}
              </div>
            </Tooltip>
          );
        }
      },
      {
        title: '報名時間',
        dataIndex: ['attributes', 'createdAt'],
        key: 'createdAt',
        render: (text) => new Date(text).toLocaleString(),
      },
      {
        title: '狀態',
        dataIndex: ['attributes', 'status'],
        key: 'status',
        render: (status) => (
          <Tag color={status === 'confirmed' ? 'green' : 'blue'} style={{ padding: '4px 8px' }}>
            {status === 'confirmed' ? '已轉換' : '未處理'}
          </Tag>
        ),
      },
      {
        title: '操作',
        key: 'action',
        width: 170,
        render: (_, record) => (
          <Space size="small" wrap>
            <Button 
              size="small"
              type="primary"
              icon={<UserAddOutlined />}
              onClick={() => convertToCustomer(record)}
              disabled={record.attributes.status === 'confirmed'}
            >
              轉換
            </Button>
            <Popconfirm
              title="確定要刪除此報名資料嗎？"
              description="此操作無法撤銷"
              onConfirm={() => handleDelete(record)}
              okText="確定"
              cancelText="取消"
            >
              <Button danger size="small" icon={<DeleteOutlined />}>
                刪除
              </Button>
            </Popconfirm>
          </Space>
        ),
      },
    ];

    return (
      <div style={{ margin: '0 -32px' }}>
        <Table
          columns={columns}
          dataSource={record.registrations}
          pagination={false}
          rowKey={record => record.id}
          size="small"
          style={{ 
            background: '#fafafa',
            margin: '0 32px'
          }}
        />
      </div>
    );
  };

  return (
    <div className={styles.registrationManagement}>
      <Card 
        title={
          <div style={{ fontSize: '18px', fontWeight: 'bold' }}>
            活動報名管理
          </div>
        }
        extra={
          <Space>
            <Button
              icon={<DownloadOutlined />}
              onClick={handleTemplateDownload}
            >
              下載範本
            </Button>
            <Upload
              accept=".xlsx,.xls"
              showUploadList={false}
              beforeUpload={handleExcelUpload}
            >
              <Button icon={<UploadOutlined />}>
                匯入 Excel
              </Button>
            </Upload>
            <Button
              type="primary"
              icon={<PlusOutlined />}
              onClick={() => setAddModalVisible(true)}
            >
              新增報名
            </Button>
            <Button
              icon={<DownloadOutlined />}
              onClick={handleExport}
              disabled={!registrations.length}
            >
              匯出 Excel
            </Button>
            <Button
              type="primary"
              icon={<UserAddOutlined />}
              onClick={handleBatchConvert}
              disabled={selectedRows.length === 0}
            >
              批量轉換
            </Button>
            <Button
              danger
              icon={<DeleteOutlined />}
              onClick={handleBatchDelete}
              disabled={selectedRows.length === 0}
            >
              批量刪除
            </Button>
          </Space>
        }
      >
        <Table
          columns={columns}
          dataSource={groupedData}
          expandable={{
            expandedRowRender,
            expandRowByClick: true,
            expandIcon: ({ expanded, onExpand, record }) =>
              expanded ? (
                <Button 
                  type="text" 
                  icon={<DownOutlined />} 
                  onClick={e => onExpand(record, e)}
                  style={{ transform: 'rotate(180deg)' }}
                />
              ) : (
                <Button 
                  type="text" 
                  icon={<DownOutlined />} 
                  onClick={e => onExpand(record, e)}
                />
              ),
          }}
          rowKey="key"
          loading={loading}
        />
      </Card>

      {/* 批量刪除確認 Modal */}
      <Modal
        title="批量刪除報名資料"
        open={batchDeleteModalVisible}
        onOk={confirmBatchDelete}
        onCancel={() => setBatchDeleteModalVisible(false)}
        okText="確認刪除"
        cancelText="取消"
        okButtonProps={{ danger: true, loading: loading }}
      >
        <p>您確定要刪除所選的 {selectedRows.length} 筆報名資料嗎？</p>
        <p style={{ color: 'red' }}>警告：此操作無法撤銷！</p>
      </Modal>

      {/* Excel 匯入預覽 Modal */}
      <Modal
        title="匯入報名資料"
        open={importModalVisible}
        onOk={handleBatchImport}
        onCancel={() => {
          setImportModalVisible(false);
          setPreviewData([]);
          setSelectedEventForImport(null);
          setSelectedSessionForImport(null);
        }}
        width={800}
      >
        <Form layout="vertical">
          <Form.Item
            label="選擇活動"
            required
          >
            <Select
              placeholder="請選擇活動"
              onChange={(value) => {
                setSelectedEventForImport(value);
                setSelectedSessionForImport(null);
              }}
              value={selectedEventForImport}
            >
              {Object.entries(events).map(([id, event]) => (
                <Option key={id} value={id}>
                  {event.title}
                </Option>
              ))}
            </Select>
          </Form.Item>

          <Form.Item
            label="選擇場次"
            required
          >
            <Select
              placeholder="請選擇場次"
              disabled={!selectedEventForImport}
              onChange={(value) => setSelectedSessionForImport(value)}
              value={selectedSessionForImport}
            >
              {selectedEventForImport && events[selectedEventForImport]?.sessions.map((session, index) => (
                <Option key={index} value={index}>
                  {session.location || `場次 ${index + 1}`}
                </Option>
              ))}
            </Select>
          </Form.Item>

          <div style={{ marginBottom: 16 }}>
            預覽資料（共 {previewData.length} 筆）：
          </div>

          <Table
            dataSource={previewData}
            columns={[
              {
                title: '姓名',
                dataIndex: 'name',
                key: 'name',
              },
              {
                title: '電話',
                dataIndex: 'phone',
                key: 'phone',
              },
              {
                title: '電子郵件',
                dataIndex: 'email',
                key: 'email',
              },
              {
                title: '備註',
                dataIndex: 'notes',
                key: 'notes',
              }
            ]}
            size="small"
            pagination={{ pageSize: 5 }}
            scroll={{ y: 200 }}
          />
        </Form>
      </Modal>

      {/* 新增報名資料 Modal */}
      <Modal
        title="新增報名"
        open={addModalVisible}
        onCancel={() => {
          setAddModalVisible(false);
          addForm.resetFields();
        }}
        onOk={handleAdd}
        width={800}
      >
        <Form
          form={addForm}
          layout="vertical"
          initialValues={{
            has_overseas_investment: false,
            budget_range: 'budget_unknown',
            attendanceCount: 1
          }}
        >
          <Row gutter={16}>
            <Col span={12}>
              <Form.Item
                name="event"
                label="活動"
                rules={[{ required: true, message: '請選擇活動' }]}
              >
                <Select
                  placeholder="請選擇活動"
                  onChange={handleEventChange}
                >
                  {Object.entries(events).map(([id, event]) => (
                    <Option key={id} value={id}>
                      {event.title}
                    </Option>
                  ))}
                </Select>
              </Form.Item>
            </Col>
            <Col span={12}>
              <Form.Item
                name="sessionIndex"
                label="場次"
                rules={[{ required: true, message: '請選擇場次' }]}
              >
                <Select placeholder="請選擇場次">
                  {selectedEventSessions.map((session, index) => (
                    <Option key={index} value={index}>
                      {session.location || `場次 ${index + 1}`}
                    </Option>
                  ))}
                </Select>
              </Form.Item>
            </Col>
          </Row>

          <Row gutter={16}>
            <Col span={8}>
              <Form.Item
                name="name"
                label="姓名"
                rules={[{ required: true, message: '請輸入姓名' }]}
              >
                <Input placeholder="請輸入姓名" />
              </Form.Item>
            </Col>
            <Col span={8}>
              <Form.Item
                name="phone"
                label="電話"
                rules={[
                  { required: true, message: '請輸入電話' },
                  { pattern: /^[0-9]{8,}$/, message: '請輸入有效的電話號碼' }
                ]}
              >
                <Input placeholder="請輸入電話" />
              </Form.Item>
            </Col>
            <Col span={8}>
              <Form.Item
                name="email"
                label="電子郵件"
                rules={[
                  { required: true, message: '請輸入電子郵件' },
                  { type: 'email', message: '請輸入有效的電子郵件' }
                ]}
              >
                <Input placeholder="請輸入電子郵件" />
              </Form.Item>
            </Col>
          </Row>

          <Row gutter={16}>
            <Col span={8}>
              <Form.Item
                name="has_overseas_investment"
                label="海外投資經驗"
                valuePropName="checked"
              >
                <Switch checkedChildren="有" unCheckedChildren="無" />
              </Form.Item>
            </Col>
            <Col span={8}>
              <Form.Item
                name="budget_range"
                label="投資預算"
              >
                <Select>
                  <Option value="budget_unknown">未知</Option>
                  <Option value="budget_under_ten">一千萬以下</Option>
                  <Option value="budget_ten_to_twenty">一千萬到兩千萬</Option>
                  <Option value="budget_twenty_to_thirty">兩千萬到三千萬</Option>
                  <Option value="budget_above_thirty">三千萬以上</Option>
                </Select>
              </Form.Item>
            </Col>
            <Col span={8}>
              <Form.Item
                name="attendanceCount"
                label="出席人數"
                rules={[
                  { required: true, message: '請選擇出席人數' }
                ]}
              >
                <Select>
                  <Option value={1}>1人</Option>
                  <Option value={2}>2人</Option>
                  <Option value={3}>3人</Option>
                  <Option value={4}>4人</Option>
                  <Option value={5}>5人</Option>
                </Select>
              </Form.Item>
            </Col>
          </Row>

          <Form.Item
            name="overseas_investment_notes"
            label="投資說明"
          >
            <Input.TextArea
              placeholder="請輸入投資相關說明"
              rows={4}
            />
          </Form.Item>

          <Form.Item
            name="notes"
            label="備註"
          >
            <Input.TextArea
              placeholder="請輸入備註"
              rows={4}
            />
          </Form.Item>
        </Form>
      </Modal>
    </div>
  );
};

export default RegistrationManagement; 